import 'dart:typed_data';
import 'package:flutter_test/flutter_test.dart';
import 'package:app/domain/signal/ble_packet.dart';

void main() {
  group('Firmware C Struct vs Dart BlePacket 12-Byte Parity Tests', () {
    test(
      'Parses exact binary byte layout generated by firmware PulsePacket struct',
      () {
        // Replicate the exact 12-byte memory layout produced by:
        // #pragma pack(push, 1)
        // struct PulsePacket {
        //     uint8_t  protocolVersion;   // Offset 0
        //     uint8_t  flags;             // Offset 1
        //     uint16_t bpmTimes10;        // Offset 2-3 (LE)
        //     uint8_t  quality;           // Offset 4
        //     uint32_t deviceTimestampMs; // Offset 5-8 (LE)
        //     uint16_t sequenceNumber;    // Offset 9-10 (LE)
        //     uint8_t  reserved;          // Offset 11 (0x00)
        // };
        // #pragma pack(pop)

        final firmwareBytes = Uint8List.fromList([
          0x01, // Offset 0: protocolVersion = 1
          0x03, // Offset 1: flags = contactDetected(bit0) | motionSuspected(bit1)
          0xE6,
          0x02, // Offset 2-3: bpmTimes10 = 742 (74.2 BPM) in Little-Endian (0x02E6)
          0x5A, // Offset 4: quality = 90
          0x40,
          0xE2,
          0x01,
          0x00, // Offset 5-8: deviceTimestampMs = 123456 (0x0001E240) in Little-Endian
          0x2A, 0x00, // Offset 9-10: sequenceNumber = 42 in Little-Endian
          0x00, // Offset 11: reserved = 0x00 (padding, no battery circuit)
        ]);

        expect(firmwareBytes.length, equals(12));

        final parsed = BlePacket.parse(firmwareBytes);
        expect(parsed, isNotNull);
        expect(parsed!.protocolVersion, equals(1));
        expect(parsed.contactDetected, isTrue);
        expect(parsed.motionSuspected, isTrue);
        expect(parsed.rawBpm, closeTo(74.2, 0.001));
        expect(parsed.quality, equals(90));
        expect(parsed.deviceTimestampMs, equals(123456));
        expect(parsed.sequenceNumber, equals(42));

        // Verify Dart encoder produces the identical 12-byte struct layout
        final encodedBytes = parsed.toBytes();
        expect(encodedBytes, equals(firmwareBytes));
        expect(encodedBytes[11], equals(0x00)); // offset 11 is reserved 0x00
      },
    );

    test('Parses calculating state (0xFFFF) from firmware struct layout', () {
      final firmwareCalculatingBytes = Uint8List.fromList([
        0x01, // Offset 0: protocolVersion = 1
        0x01, // Offset 1: contactDetected=1, motionSuspected=0
        0xFF, 0xFF, // Offset 2-3: bpmTimes10 = 0xFFFF (calculating/invalid)
        0x32, // Offset 4: quality = 50
        0x00, 0x10, 0x00, 0x00, // Offset 5-8: deviceTimestampMs = 4096 ms
        0x05, 0x00, // Offset 9-10: sequenceNumber = 5
        0x00, // Offset 11: reserved = 0x00
      ]);

      final parsed = BlePacket.parse(firmwareCalculatingBytes);
      expect(parsed, isNotNull);
      expect(parsed!.rawBpm, isNull);
      expect(parsed.contactDetected, isTrue);
      expect(parsed.motionSuspected, isFalse);
      expect(parsed.quality, equals(50));
      expect(parsed.deviceTimestampMs, equals(4096));
      expect(parsed.sequenceNumber, equals(5));

      final roundTrip = parsed.toBytes();
      expect(roundTrip, equals(firmwareCalculatingBytes));
    });
  });
}
